// Get the AI response
let aiOutput = $json.output;

// If output is not a string, return it directly
if (typeof aiOutput !== "string") {
  return [
    {
      json: aiOutput
    }
  ];
}

// Remove markdown code blocks if they exist
aiOutput = aiOutput
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

try {
  // Parse the JSON string
  const parsed = JSON.parse(aiOutput);

  return [
    {
      json: parsed
    }
  ];
} catch (error) {
  return [
    {
      json: {
        success: false,
        error: error.message,
        raw_output: aiOutput
      }
    }
  ];
}

for (const item of items) {
  const topic = String(item.json.Topic || "").trim();
  const status = String(item.json.Status || "").trim().toLowerCase();
  const id = String(item.json.ID || "").trim();

  if (id !== "" && topic !== "" && status === "pending") {
    return [item];
  }
}

return [];
